/* GeoSR editorial homepage — concept imagery is replaced through documented media slots */
const expertiseScenes = [
  {k:'관측과 조사',e:'Observation & survey',leadK:'현장을 정밀하게',leadE:'Closer to the field',bodyK:'육상에서 하천과 해양까지\n측량과 현장 관측으로 환경의 기초 자료를 확보합니다',bodyE:'Precision surveys and observations\nacross land, rivers and oceans',image:'coastal-survey-source.png',source:true,tagsK:['육상·수로 측량','해양 관측','무인 관측'],tagsE:['Land & hydrographic surveys','Ocean observation','Uncrewed systems'],page:'equipment'},
  {k:'환경과 생태',e:'Environment & ecology',leadK:'환경을 깊이 있게',leadE:'A deeper understanding',bodyK:'수질과 퇴적물의 화학분석부터 생태 조사까지\n다양한 관점에서 환경의 상태를 평가합니다',bodyE:'Chemical analysis and ecological surveys\nreveal the condition of aquatic environments',image:'analysis-concept.png',tagsK:['환경 분석','생태 조사','환경 평가'],tagsE:['Chemical analysis','Ecological surveys','Environmental assessment'],page:'business',params:{id:84}},
  {k:'수치모델과 예측',e:'Modelling & prediction',leadK:'변화를 예측하다',leadE:'Understand what comes next',bodyK:'기상과 유역에서 하천과 연안까지\n수치모델로 환경 변화와 재해 영향을 분석합니다',bodyE:'Numerical models investigate environmental change\nand hazard impacts across watersheds and coasts',image:'coastal-model-v3.png',tagsK:['수환경 모델','재해 예측','영향 분석'],tagsE:['Aquatic models','Hazard prediction','Impact analysis'],page:'business',params:{id:46}},
  {k:'AI와 원격탐사',e:'AI & remote sensing',leadK:'더 넓게 분석하다',leadE:'A wider perspective',bodyK:'위성영상과 환경 데이터에 AI를 적용해\n예측과 탐지의 가능성을 넓혀갑니다',bodyE:'AI and satellite imagery extend our ability\nto predict change and detect patterns',image:'satellite-layers-v3.png',tagsK:['환경 AI','위성영상','공간정보'],tagsE:['Environmental AI','Satellite imagery','Spatial information'],page:'business',params:{id:61}}
];

function expertisePanel(i=0){const d=expertiseScenes[i];return `<div class="expertise-photo" data-production-slot="expertise-${i+1}"><img src="assets/${d.image}" alt="${E(T(d.k,d.e))} — ${d.source?T('GeoSR 원본 자료','GeoSR source material'):T('영상 가안','film concept')}" loading="lazy"><span class="media-note">${d.source?T('GEOSR 현장 자료','GEOSR FIELD REFERENCE'):T('기술 연출 가안 · 실제 해석 결과 아님','VISUAL CONCEPT · NOT A VERIFIED ANALYSIS')}</span></div><div class="expertise-details"><span class="scene-index">0${i+1} / 04</span><h3>${T(d.leadK,d.leadE)}</h3><p>${T(d.bodyK,d.bodyE).replaceAll('\n','<br>')}</p><div class="expertise-tags">${(en?d.tagsE:d.tagsK).map(t=>`<span>${t}</span>`).join('')}</div>${A(U(d.page,d.params||{}),'관련 기술 보기','Explore the technology','plain-arrow')}</div>`}

function home(){return `
<section class="landscape-hero" data-production-slot="geosr-hero" data-film-slot="geosr-hero" data-motion-lab-hero>
 <img class="landscape-image" src="assets/estuary-hero-v4.png" alt="${T('서해안 조간대와 수로를 모티브로 한 영상 콘셉트','Film concept inspired by Korean west-coast tidal landscapes')}" fetchpriority="high">
 <canvas class="motion-lab-canvas" data-motion-lab-canvas aria-hidden="true"></canvas>
 <div class="landscape-vignette"></div>
 <div class="hero-edition"><span>GEOSYSTEM RESEARCH</span><span>${T('관측에서 예측까지','FROM OBSERVATION TO PREDICTION')}</span></div>
 <div class="landscape-title"><p>SCIENCE BEYOND THE VISIBLE</p><h1>Beyond<br>the surface</h1></div>
 <div class="landscape-caption"><p>${T('자연환경을 이해하는 기술<br>현장의 질문에서 새로운 해답까지','Engineering a deeper understanding<br>From real-world questions to new answers')}</p><a class="round-explore" href="#expertise" aria-label="${T('기술 소개로 이동','Explore our expertise')}">↓</a></div>
 <div class="landscape-footer"><span>LAND · WATER · OCEAN · SPACE</span><span>${T('영상 콘셉트 · 실제 지형 자료 아님','FILM CONCEPT · NOT GEOGRAPHIC DATA')}</span><button type="button" class="landscape-motion" aria-pressed="false">${T('모션 정지','Pause motion')} Ⅱ</button></div>
</section>
<section class="science-intro" id="expertise">
 <div class="science-label"><span class="tiny-index">01 — GEOSR EXPERTISE</span><p>${T('현장에서 시작해<br>더 넓은 해답으로','From the field<br>to a bigger picture')}</p></div>
 <div class="science-statement"><h2>${T('현장을 관측하고<br><span>환경의 변화를 예측합니다</span>','Observe the present<br><span>Understand what comes next</span>')}</h2><div class="science-intro-bottom"><p>${T('육상과 하천에서 연안과 해양까지<br>조사와 분석에 수치모델과 AI를 더해<br>복잡한 환경 문제를 풀어갑니다','From land and rivers to coasts and oceans<br>We connect field research with modelling and AI<br>to address complex environmental challenges')}</p>${A(U('business'),'기술과 솔루션','Our expertise','ink-link')}</div></div>
</section>
<section class="field-story" aria-label="${T('관측에서 예측으로 이어지는 기술','From field observation to prediction')}">
 <div class="field-stage">
  <div class="field-story-top"><span>ONE CONNECTED PERSPECTIVE</span><span class="field-count">01 / 04</span></div>
  <div class="field-frames">${expertiseScenes.map((d,i)=>`<div class="field-frame ${i===0?'is-active':''}" data-frame="${i}" data-film-slot="expertise-${i+1}" data-film-active="${i===0}"><img src="assets/${d.image}" alt="${E(T(d.k,d.e))} — ${d.source?T('회사 공개 자료','Company source'):T('기술 영상 가안','Film concept')}" loading="lazy"></div>`).join('')}</div>
  <div class="field-shade"></div>
  <div class="field-copy">${expertiseScenes.map((d,i)=>`<article class="field-chapter ${i===0?'is-active':''}" data-chapter="${i}" ${i?'inert':''}><span>0${i+1} / ${d.e.toUpperCase()}</span><h2>${T(d.k,d.e)}</h2><p>${T(d.bodyK,d.bodyE).replaceAll('\n','<br>')}</p>${A(U(d.page,d.params||{}),'관련 기술 살펴보기','Explore this discipline','field-link')}</article>`).join('')}</div>
  <div class="field-navigator" role="group" aria-label="${T('기술 장면 선택','Choose a discipline')}">${expertiseScenes.map((d,i)=>`<button type="button" data-chapter-go="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${T(d.k,d.e)}<i></i></button>`).join('')}</div>
  <small class="field-disclaimer">${T('회사 자료와 기술 연출 가안으로 구성 · 실제 해석 결과 아님','SOURCE IMAGERY & FILM CONCEPTS · NOT VERIFIED ANALYSIS')}</small>
 </div>
</section>
<section class="digital-section" id="platforms">
 <div class="digital-title"><span class="tiny-index">02 — DIGITAL PLATFORMS</span><h2>${T('기술을 손끝에','Intelligence<br>in your hands')}</h2><p>${T('GeoSR의 연구가 실제로 작동하는 곳','Where our research comes to life')}</p></div>
 <article class="digital-feature ax-feature"><div class="digital-copy"><span class="tiny-index">APPLIED INTELLIGENCE</span><h3>AX <em class="ax-name">Platform</em><span>↗</span></h3><p>${T('탐지에서 예측과 모니터링까지','Detection · Prediction · Monitoring')}</p><div class="digital-description">${T('해양·환경 분야의 문제를 해결하는<br>목적별 응용 플랫폼을 소개합니다','Discover specialised applications<br>for marine and environmental challenges')}</div>${A(U('ax-platform'),'9개 플랫폼 살펴보기','Explore 9 platforms','pill-link')}</div>${axFilmReel()}</article>
 <article class="digital-feature dap-feature"><div class="digital-copy"><span class="tiny-index">EARTH DATA PLATFORM</span><h3>GeoDAP<span>↗</span></h3><p>Earth Data Intelligence</p><div class="digital-description">${T('관측과 모델에서 위성 데이터까지<br>지구환경 데이터를 한곳에서 탐색합니다','Explore observations, models<br>and satellite data in one place')}</div><a class="pill-link" href="https://www.geo-dap.com/" target="_blank" rel="noopener">${T('GeoDAP 바로가기','Open GeoDAP')} <span>↗</span></a></div><a class="digital-screen dap-screen" href="https://www.geo-dap.com/" target="_blank" rel="noopener" aria-label="${T('GeoDAP 새 창에서 열기','Open GeoDAP in a new tab')}"><div class="screen-top"><span>GEODAP / EARTH DATA</span><span>${T('독립 서비스','INDEPENDENT PLATFORM')}</span></div><img src="assets/platform-geodap.png" alt="${T('GeoDAP 지구환경 데이터 탐색 화면','GeoDAP Earth data interface')}" loading="lazy"></a></article>
</section>
${credentialGallery()}
<section class="research-editorial-section new-research"><div class="section-kicker"><span>04 / RESEARCH & NEWS</span>${A(U('research'),'전체보기','View all','plain-arrow')}</div><div class="research-title-row"><h2>${T('연구는 계속됩니다','Research<br>moves forward')}</h2><p>${T('현장에서 전하는 새로운 소식','New perspectives from the field')}</p></div><div class="editorial-records">${[posts[1],posts[3],posts[2]].map((p,i)=>`<a class="editorial-record" href="${U(p[1]==='notice'?'news':'research',{id:p[0]})}"><span class="editorial-number">0${i+1}</span><div><span class="editorial-type">${T(...types.find(t=>t[0]===p[1]).slice(1))}</span><h3>${E(T(p[3],p[4]))}</h3></div><time>${p[2].replaceAll('-',' / ')}</time><span class="editorial-arrow">↗</span></a>`).join('')}</div></section>`}


function axFilmReel(){
 const scenes=[
  {id:'detect',name:'Detect',ko:'탐지',k:'위성영상 속 양식시설을 구분하는 과정',e:'Identifying aquaculture facilities in satellite imagery',platforms:'SATELLITE AI'},
  {id:'predict',name:'Predict',ko:'예측',k:'태풍 시나리오에 따른 해수면과 연안 침수의 변화',e:'Sea-level and coastal inundation changes under typhoon scenarios',platforms:'FLOOD 3D · STORM SURGE · SEA LEVEL'},
  {id:'monitor',name:'Monitor',ko:'모니터링',k:'관측 지점에서 해역까지 해양환경을 살피는 과정',e:'Following marine conditions from observation stations to regional waters',platforms:'OCEAN BUOY · OCEAN ENVIRONMENT · COASTAL SAFETY'}
 ];
 return `<div class="ax-reel-wrap"><div class="ax-reel"><div class="ax-reel-heading"><span>AX / IN FOCUS</span><span>${T('영상 제작 대기','FILM IN PREPARATION')}</span></div><div class="ax-reel-viewport">${scenes.map((s,i)=>`<section class="ax-reel-panel" id="ax-panel-${s.id}" role="tabpanel" aria-labelledby="ax-tab-${s.id}" tabindex="0" data-film-slot="ax-${s.id}" data-film-active="${i===0}" ${i?'hidden inert':''}><div class="ax-reel-placeholder"><small>0${i+1} / ${T('장면 구성안','SCENE OUTLINE')}</small><strong>${s.name}</strong><p>${T(s.k,s.e)}</p></div><div class="ax-reel-platforms">${s.platforms}</div><button class="ax-film-toggle" type="button" data-film-toggle="ax-${s.id}" aria-label="${T('영상 재생 또는 일시정지','Play or pause film')}" aria-pressed="false" hidden>Ⅱ</button></section>`).join('')}</div><div class="ax-reel-tabs" role="tablist" aria-label="${T('AX 영상 장면','AX film scenes')}">${scenes.map((s,i)=>`<button type="button" id="ax-tab-${s.id}" role="tab" aria-controls="ax-panel-${s.id}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-ax-scene="${i}"><span>0${i+1}</span>${T(s.ko,s.name)}</button>`).join('')}</div></div><p class="ax-reel-note">${T('각 플랫폼의 실제 기능을 바탕으로 구성한 영상 자리입니다','Film slots based on the actual functions of each platform')}</p></div>`;
}

function credentialGallery(){return `<section class="credential-section" id="credentials" aria-labelledby="credential-heading"><div class="section-kicker"><span>03 / PATENTS & CERTIFICATIONS</span><span>RESEARCH THAT BUILDS</span></div><div class="credential-intro"><h2 id="credential-heading">Built on<br><span>research</span></h2><div><p>${T('GeoSR의 특허와 기술 인증','Patents and certifications from GeoSR')}</p><p class="muted">${T('쌓아온 기술을 기록으로 확인하세요','Explore the records behind our expertise')}</p><div class="gallery-controls"><button type="button" data-gallery-step="-1" aria-label="${T('이전 자료','Previous document')}">←</button><span id="credential-status" aria-live="polite">01 / 07</span><button type="button" data-gallery-step="1" aria-label="${T('다음 자료','Next document')}">→</button></div></div></div><div class="credential-rail" tabindex="0" role="region" aria-label="${T('인증서·특허 가로 갤러리','Horizontal patent and certification gallery')}" aria-describedby="credential-hint"><div class="credential-loading">${T('자료를 불러오는 중','Loading documents')}</div></div><div class="credential-bottom"><p id="credential-hint">${T('좌우로 넘겨보기 · 자료를 선택하면 확대됩니다','Swipe or use the arrows · Select a document to enlarge')}</p><a href="${U('company')}#credential-library">${T('인증·면허·지식재산권 전체보기','Explore the document collection')} ↗</a></div></section><dialog id="credential-dialog" aria-labelledby="credential-dialog-title"><div class="document-modal-head"><h2 id="credential-dialog-title"></h2><button type="button" data-close-document aria-label="${T('닫기','Close')}">×</button></div><img alt=""><div class="document-modal-foot"><p>${T('기존 홈페이지에 공개된 자료의 사본','A copy of the record published on the original website')}</p><a target="_blank" rel="noopener">${T('문서 사본 열기','Open document copy')} ↗</a></div></dialog>`}

function modernFooter(){return `<section class="contact-editorial"><div class="contact-editorial-top"><p class="eyebrow">CONNECT WITH GEOSR</p><span>${T('사업과 연구의 다음 파트너','YOUR NEXT RESEARCH & ENGINEERING PARTNER')}</span></div><a href="${U('contact')}" class="contact-statement"><h2>Let’s move<br><span>forward</span></h2><span aria-hidden="true">↗</span></a><div class="contact-editorial-bottom"><p>${T('사업·기술 문의 및 연구 협력','Projects, technology enquiries and research partnerships')}</p><a href="mailto:admin@geosr.com">admin@geosr.com ↗</a></div></section><footer class="site-footer"><div class="footer-information"><div><a class="brand" href="${U('index')}"><img src="assets/logo.png" alt="GeoSR"></a><p>${T('지오시스템리서치','GeoSystem Research Corporation')}<br>${T('경기도 군포시 엘에스로 172 한림휴먼타워 306호','306 Hanlim Human Tower, 172 LS-ro, Gunpo-si, Korea')}</p><a href="tel:+823151805700">+82 31 5180 5700</a></div><div class="footer-navigation">${nav.map(n=>A(U(n[0]),n[1],n[2])).join('')}${A('https://www.geo-dap.com/','GeoDAP','GeoDAP')}</div><div class="footer-meta"><span>© GEOSYSTEM RESEARCH</span><p>${T('디자인 목업<br>생성 이미지는 영상 제작을 위한 가안입니다','DESIGN PROTOTYPE<br>Generated imagery represents proposed films')}</p>${A(U('equipment'),'관측·장비','Observation & equipment')}</div></div><div class="footer-wordmark" aria-hidden="true">GeoSR<span>®</span></div></footer>`}
